#!/usr/bin/env python3
"""Publish verified primary TempGlitch 2026 results, not VLM or video inference.

The official arxiv HTML complete source (with 12 author VLM confusion matrices)
and all 1500 original HuggingFace source file listing metadata have independently
verified SHA snapshots under /data/var. Derive and retain compact aggregate
with exact original TP/TN/FP/FN, per-category size-only negative-control audit,
model checkpoint versions and provenance. No 60GB video files or 4xL40S calls,
no source media, author labels derived by their in-engine source assignment.
All third-party input bytes remain outside Git; NO artificial model score is
reported as actual Nitro/Thor local inference or human-blind video judgements.
"""
from pathlib import Path
import json,hashlib,datetime,statistics
VAR=Path('/data/var/perceptual-independent-20261024/tempglitch-control-20261025')
REPO=Path(__file__).resolve().parents[2]
DOC=REPO/'docs/research/perceptual-tempglitch-primary-video-evidence-2026-10-25.md'
OUT=REPO/'docs/research/perceptual-tempglitch-1500-source-evidence-2026-10-25.json'

def load(name):
 b=(VAR/name).read_bytes();return json.loads(b),hashlib.sha256(b).hexdigest()

def render():
 if OUT.exists() or DOC.exists():print('PREVIOUS_PRIMARY_TEMPGLITCH_COMPACT_SOURCE_EVIDENCE_PRESERVED');return
 source,hsource=load('full_1500_original_metadata_and_pair_integrity_20261025.json')
 models,hmodels=load('all_12_source_vlm_exact_error_matrices_20261025.json')
 assert source['paired_source_crossvalidated_metadata_only_binary_result']['n_total_video_files']==1500
 assert len(source['original_source_file_listing'])==1500
 assert set(source['category_source_pair_size_distributions'])=={'Blinking','Frozen Animation','Shooting Error','Stuck in Place','Velocity Bug'}
 assert source['category_source_pair_size_distributions']['Stuck in Place']['original_pair_env_counts']=={'Platformer':75,'TPS':75}
 assert models['author_model_count']==12 and models['author_archived_runs']==22
 assert models['best_overall_author_accuracy']['model']=='GPT 5.4 Mini'
 assert (models['best_overall_author_accuracy']['true_positives'],models['best_overall_author_accuracy']['false_positives'])==(173,112)
 assert models['models']['Qwen3VL 8B']['source_evaluations']['sampled_5fps']['FN']==748
 assert models['models']['Gemini 3 Flash']['source_evaluations']['native_raw_video']['FP']==650
 assert models['simple_untrained_input_ignoring_policies']['always_predict_glitch']['f1_pct']>66.6
 source_sha=hashlib.sha256((VAR/'source_paper_arxiv_2605_21443v1.html').read_bytes()).hexdigest()
 assert source_sha==models['original_arxiv_html_sha256']
 pick={}
 for name in ['GPT 5.4 Mini','Qwen3VL 8B','Qwen3.6 27B','Gemini 3 Flash','Gemma4 31B','GPT 5.5']:
  entry=models['models'][name]
  pick[name]={'provider':entry['provider'],'original_source_model_checkpoint':entry['exact_published_model_version'],'settings':entry['source_evaluations']}
 meta=source['paired_source_crossvalidated_metadata_only_binary_result']
 result={'date':'2026-10-25',
 'research_owner':'SWAAG primary-research perceptual analyzer choices, original testing/GUI/media instructions',
 'source':'TempGlitch arxiv:2605.21443v1 and original asgaardlab/TempGlitch HuggingFace MIT dataset source; 750 engineered temporal gameplay video glitches + 750 source normal category controls',
 'original_full_dataset_godot_engine_and_game_environments':'Two Godot authored demo environments, five known temporal glitch mechanisms with 150 clean/150 buggy in each; SOURCE AUTHORS encoded labels from injected logic, not external blind adjudicators',
 'primary_arxiv_html_source_sha256':source_sha,
 'raw_research_snapshots_sha256':{'published_confusion_reanalysis_22_model_settings':hmodels,'complete_1500_clip_size_source_and_pair_integrity':hsource},
 'complete_real_source_records_not_committed_to_git':True,
 'independent_video_download_or_local_VLM_inference':False,
 'actual_author_evaluation':{'dataset_video_n':1500,'n_clean_original':750,'n_glitchy_injected':750,'n_vlms':12,'n_model_input_settings_scored':22,'paper_model_results_recomputed_from_author_actual_TP_TN_FP_FN':True,'best_overall':models['best_overall_author_accuracy'],'selected_model_exact_source_matrices':pick,'trivial_all_glitch_policy':models['simple_untrained_input_ignoring_policies']['always_predict_glitch'],'trivial_all_clean_policy':models['simple_untrained_input_ignoring_policies']['always_predict_clean'],'authors_implementation':'Open weight six model inference used four NVIDIA L40S GPUs via Unsloth; proprietary models provider APIs; no local Nitro/Thor VLM or latency/price claim'},
 'full_original_video_file_metadata_independent_audit':{'all_source_files':1500,'source_git_revision':source['revision'],'original_category_matched_pairs':750,'Stuck_in_Place_environment_reused_numeric_IDs':'75 Platformer IDs plus 75 TPS IDs, do not pair numeric IDs without environment','source_category_file_size_statistics':source['category_source_pair_size_distributions'],'metadata_size_only_source_pair_heldout_model':meta,'metadata_only_per_category_source_holdout':source['per_category_metadata_only_heldout'],'important_warning':'File bytes and source group are not part of typical frame-only VLM inputs; this is dataset construction leakage risk and an intentionally nonvisual baseline, NOT a model proving a video defect.'},
 'verdict':'No full-video/general VLM judge tested achieves acceptable miss/false alarm rates for author-injected temporal gameplay anomalies. Best author accuracy 54.1pct, near chance balanced dataset. Qwen3-VL-8B 5 FPS TP2 FN748 FP0, an always-clean bias. Gemini3 Flash raw video TP654 FN96 FP650, an almost-everything-is-defective bias. Authors source tables independently rechecked. Metadata-only clip size/class classifier 56.6pct heldout on 320 separate source files, cannot be directly statistically compared to VLM on all1500.',
 'conditional_immediate_tool_selection':'Source/DOM geometry and exact approved timeline for hard known constraints; OCR/feature tracking/pHash as evidence and abstain where uncertain, no VLM automatic verdict. For engine temporal failures, require object-level state, pose and displacement continuity or debug instrumentation, distinguish world-state defects from full-frame stalls. Any VLM recommendation requires new source-engine, human clean/defective labels, calibrated per-type FN/FP, latency and work-group contention tests.',
 'limitations':['Published author in-engine source glitch/normal truth is not blind independent subjective fault annotation; output cannot establish perceptual natural render stalls.','Published models were run by authors, on four L40S for open-model family, not locally on Thor/Nitro; service versions, quantization, prompts and workloads differ.','Only two Godot demo environments; clip variants correlate within source and scene, and published Table3 does not provide a heldout new rendering engine result.','Some models obtain high recall simply by predicting nearly all videos glitchy; always-glitch untrained baseline F1 66.7pct on 1:1 class data.','Higher sampling frame rate from 1 to 5 FPS does not consistently improve practical accuracy or model calibration; Gemini raw-video accuracy still near chance.','The source metadata 320-file heldout split trained on other indices from the SAME source engine and categories, not untouched external game generators; source file size may encode duration, bitrate or scene content.','Source frozen animation means CHARACTER POSE not updating while world video continues; FFmpeg whole-screen freezedetect cannot prove absence of this anomaly.','Source original dataset videos ~60GB were deliberately not downloaded to avoid production resource contention and source media redistribution; quantitative VLM confusion is literature, not reproduced model inference.','No event-level temporal IoU or defect timing ground truth extracted and no natural-visual-quality human MOS on new source provided.']}
 OUT.write_text(json.dumps(result,indent=2)+'\n')
 chosen=[('Gemini 3 Flash','native_raw_video'),('GPT 5.4 Mini','sampled_5fps'),('Qwen3.6 27B','sampled_5fps'),('Qwen3VL 8B','sampled_1fps'),('Qwen3VL 8B','sampled_5fps'),('Gemma4 31B','sampled_5fps'),('GPT 5.5','sampled_5fps')]
 lines=[]
 for name,setting in chosen:
  row=models['models'][name]['source_evaluations'][setting]
  lines.append(f"| {name} | {setting.replace('_',' ')} | {row['TP']} | {row['FN']} | {row['FP']} | {row['TN']} | {row['accuracy_pct']:.1f}% | {row['false_positive_rate_pct']:.1f}% |")
 doc=f'''# Real temporal video glitch QA: verified primary-model failure and full-release source shortcut audit\n\n**25 October 2026. Research verdict: PARTIAL; no qualified autonomous video QA model.** This is a substantive incremental original-source study for the owner's September testing recording and SWAAG visual analyzer research. It does not repeat the already verified source-video edits, GUI/slide, diagram or warehouse mechanical experiments. We inspected the May 2026 primary paper [TempGlitch: Evaluating Vision-Language Models for Temporal Glitch Detection in Gameplay Videos](https://arxiv.org/html/2605.21443), its linked [MIT Hugging Face original dataset](https://huggingface.co/datasets/asgaardlab/TempGlitch), and reanalyzed **all 1,500 original release video file metadata entries**, plus **all twelve original published VLM confusion matrices** across **twenty-two model/input configurations**. The author's actual model calls were **not** repeated on Nitro, Thor or a paid API. Entire source video release about 60.3 GB was deliberately not downloaded because production GPU/CPU/network processes were active. Source HTML SHA256 and 1,500-file name-size manifests remain under isolated `/data/var/perceptual-independent-20261024/tempglitch-control-20261025`; only code and compact aggregated source-derived evidence are in Git.\n\n## What is actually grounded by independent source and what is not\n\nThe benchmark consists of **750 buggy and 750 category-matched normal** real rendered gameplay recordings from two controlled Godot demo environments, divided equally into **blinking/flicker, incorrect shooting, velocity/teleportation, frozen character animation and stuck-in-place motion**. The bugs were deliberately injected by the dataset authors (and one existing shooting behavior), generally during a middle portion of the clip; the original normal pair is a similar gameplay situation and is *not necessarily a pixel-aligned alternate render of the same exact source events*. No blind independent human defect acceptance votes were provided for the full 1,500 clips. Notably, *frozen animation means the **character's pose** remains frozen while video/camera/world may continue moving*; it is not the same as a full-screen playback freeze measurable by FFmpeg `freezedetect`. The original paper evaluates **six proprietary and six open-weight VLMs**, open weights using **four NVIDIA L40S GPUs**, Gemini with native video input and other models with up to 50 sampled frames at one or five FPS, using a prompt requesting a JSON defect verdict. The authors retry malformed output until a valid JSON, so pure end-to-end format/latency reliability was not measured by the published accuracy.\n\nThe published source [main Table 3 and Appendix E confusion matrices](https://arxiv.org/html/2605.21443) contain exact true positives, false positives, false negatives and true negatives for every evaluated model. We independently parsed the actual arXiv HTML, recomputed accuracy, precision, recall and F1 from every original confusion row, validated all 22 reported source metric rows against the authors' table to within 0.11 percentage points, and checked exact checkpoint IDs against paper Appendix A. The primary table below is **author-run VLM inference**, not a local experiment, on **750 positives and 750 negatives** for each model configuration.\n\n| Exact author model/run | Input | True glitches detected | Missed glitches | Clean videos falsely flagged | Correctly accepted clean | Overall accuracy | Clean false-alarm rate |\n|---|---|---:|---:|---:|---:|---:|---:|\n'''+"\n".join(lines)+"\n\n"
 doc+='''The strongest original accuracy was only **54.1%** for GPT-5.4 Mini using five sampled frames per second, with 577 missed glitches and 112 false alarms on 750 clean clips. Qwen3-VL 8B at five FPS reported **two of 750 detected and 748 missed**, zero clean false alarms: apparently perfect precision is a consequence of almost never predicting positive. By contrast, Gemini 3 Flash with native video accepted only 100 of 750 clean clips, flagging **650 false alerts** while finding 654 positives. Qwen3.6 27B is more balanced but around 50.5% overall accuracy. On this balanced benchmark, a trivial model that always says **glitch** has 50% accuracy and **66.7% F1**, so F1 alone can actively mislead deployment decisions. The reported Qwen3-VL checkpoint is `Qwen3-VL-8B-Instruct-unsloth-bnb-4bit` and is **not a new test of the owner's existing Thor deployment**; Qwen3.6 27B also must not be conflated with Qwen3.8 27B workers.\n\n## Independent full-release metadata-only negative control: 1,500 cases\n\nThe public original release lists every encoded `.mp4` source size even when the actual footage is not downloaded. We independently retrieved the authoritative source list from all five category directories, verified **150 clean and 150 buggy originals in each**, and corrected an easily missed identity issue: the Stuck in Place category has 75 Platformer source IDs and 75 TPS source IDs, reusing numbers one through seventy-five. Pairing by number without the original engine would be scientifically invalid. No data or original source media were modified. The complete source hash receipt is retained outside Git.\n\nWe then froze a simple deliberately **nonvisual** classification procedure: per-category/per-engine interactions with logarithm of MP4 byte size, L2 logistic regularization with fixed parameters and category-paired IDs assigned to train versus evaluation by deterministic SHA256. The model trained on **1,180** source files and evaluated on **320** previously withheld source files (160 source buggy, 160 source normal). The test produced **87 true positives, 73 misses, 66 false clean-video accusations and 94 correct clean results**, **56.6% balanced accuracy**, and **0.599 ROC AUC**. A 2,500-resample source-pair bootstrap gives descriptive 95% ROC interval **0.547–0.653** and balanced accuracy **0.519–0.613**. This does not establish model capability—**not a single video pixel was inspected**—but shows a measurable dataset-construction signal that should be included as a trivial control in future development benchmarks. The comparison is *not statistically head-to-head* against the 1,500-case published VLM leaderboard because the held-out sample and features differ.\n\nFile-size asymmetry varies by category. For **Frozen Animation**, original buggy median file size was about **36.5 MiB** versus **48.1 MiB** for the source clean category; size-only category-heldout ROC AUC was **0.724** over 48 reserved clips (24 per class). Other categories had different directions or weaker correlations. File bytes can reflect video duration, codec/bitrate, camera style or visual complexity; without separately accounting for these, a claimed new model improvement might actually be exploiting a source shortcut. The VLM paper fed videos or sampled frames, **not the exact encoded file-size feature**, so this source signal is **not evidence** that any evaluated VLM used it. The 320-file test comes from the same controlled two engine scenes, not unseen commercial production footage.\n\n## Which real tool combination follows from these numbers?\n\nThe source-wide results independently support the original owner conclusion, with new concrete error rates. A release inspector should first enforce **documented source correctness** when available: strict frame timestamp order and duration, approved cuts/fades/holds, exact source video identity and audio synchronization. For computer-generated 3D game/video, use engine object state, position/velocity/pose and intended action constraints for genuine physical failures. Image-based OCR/CV, pHash, optical flow and FFmpeg freeze detection are task-specific evidence collectors, not reliable intent/physics/quality approval judges. A VLM can produce a candidate explanation for uncertain video segments but cannot override exact reference/physics checks or author-approved events without independent calibration. An intact 30-FPS presentation timeline does not itself prove continuous perceived motion. A character frozen in pose may occur while every full-screen frame changes, so no-reference video-level freezing algorithms can fail for structural reasons.\n\n**Open decisive source gap:** a previously unused class of real production and game footage, independently human-reviewed as clean/defective with precise bad-frame intervals, paired with the same source, camera/FPS/codec settings and expected object behavior; evaluate specific deterministic source, object tracker and modern VLM choices for miss/false-alarm rate, event localization and resource cost. TempGlitch's 750/750 controlled source is useful, but self-authored in-engine labels and two demo engines are not a generalized industrial, live-stream playback or human-objectionable acceptance corpus. The former denied video result retrievals remain denied and were not retried, and no calendar events or production GPUs were used. **Overall objective PARTIAL.**\n'''
 DOC.write_text(doc)
 print('VERIFIED_SOURCE_LINKED_TEMPGLITCH_RESEARCH_ARTIFACTS',OUT.stat().st_size,'JSON_BYTES',DOC.stat().st_size,'MARKDOWN_BYTES',flush=True)
if __name__=='__main__':render()
